  for(const c of rolling){const st=await page.evaluate(pos=>window.__L8Q.parse(pos),c.pos);const legal=await page.evaluate(s=>window.__L8Q.legal(s),st);const ref=await page.evaluate(async s=>window.AI_SHOGI_YANEURAOU_FUTURE.bestMove(s,{ms:4000,multiPV:5,adaptive:false}),st);const rc=(ref?.info?.candidates||[]).filter(x=>x?.token).sort((a,b)=>(a.rank||99)-(b.rank||99)).slice(0,5),rb=rc[0];if(!rb?.token)throw Error('no ref '+c.series+'/'+c.ply);console.log('BOUNDARY_REF '+JSON.stringify({series:c.series,rollingPly:c.ply,sourcePly:c.sourcePly,turn:(c.pos.split(/\s+/)[1]||''),best:rb.token,depth:ref?.info?.depth||0,nodes:ref?.info?.nodes||0,candidates:rc.map(x=>({rank:x.rank,token:x.token,cp:x.cp,mate:x.mate}))}));for(const d of duels){for(const side of ['hi','lo']){const t=targets[d[side]],res=await callTarget(t,st),u=res?.move?await page.evaluate(m=>window.__L8Q.usi(m),res.move):String(res?.info?.bestmove||'');if(!u||!legal.includes(u))throw Error('illegal '+d.label+' '+side+' '+c.series+'/'+c.ply+' '+u);const hit=rc.find(x=>x.token===u);let loss=2000;if(u===rb.token)loss=0;else if(hit&&Number.isFinite(rb.cp)&&Number.isFinite(hit.cp))loss=Math.max(0,rb.cp-hit.cp);const z=stats[d.label][side];z.exact+=u===rb.token?1:0;z.top5+=hit?1:0;z.loss.push(loss);z.outside+=hit?0:1;const row={duel:d.label,side,rating:t.rating,name:t.name,series:c.series,rollingPly:c.ply,sourcePly:c.sourcePly,turn:c.pos.split(/\s+/)[1],token:u,exact:u===rb.token,top5:!!hit,refRank:hit?.rank||0,refLoss:loss,selectedRank:Number(res?.info?.selectedRank||1),internalLoss:Number(res?.info?.cpLoss||0),depth:Number(res?.info?.depth||0),nodes:Number(res?.info?.nodes||0),targetMs:Number(res?.targetMs||0)};z.rows.push(row);console.log('BOUNDARY_ROW '+JSON.stringify(row));}}}
